    },
    {
      "design": "d3r3B",
      "good": "All five columns are visible at once. English phrases wrap into recognizable words.",
      "problems": "Identifiers and Arabic words split, three language headers wrap, and Chinese and Japanese become nearly vertical character stacks. The very tall rows make lookup and comparison difficult.",
      "cause": "The 130px key column cannot contain the identifiers. The 45px Chinese and Japanese columns and 53px Arabic column leave too little text space after padding."
    },
    {
      "design": "d3r1A",
      "good": "The first viewport shows complete keys and the English reference together. The table is considerably narrower than d3r3A, and its two-line maximum keeps rows reasonably compact.",
      "problems": "English wraps several short phrases, and Chinese breaks the email and shipping messages at less comfortable points. A measured word break remains, and the other languages require scrolling.",
      "cause": "The 132px English and 120px Chinese columns are tight for longer phrases; the 145px Arabic column also requires wrapping. The 227px key column leaves only about 132px for English in the first viewport."
    },
    {
      "design": "d3r2C",
      "good": "All columns are visible, and the extra space given to Japanese and Arabic improves their line lengths compared with d3r3B. Its rows are substantially shorter.",
      "problems": "Keys still split repeatedly, Chinese reads as a vertical stack, and the Japanese and Arabic headers wrap. Arabic words also break, weakening continuous reading and comparison.",
      "cause": "The 112px key and 48px Chinese columns are too narrow for their contents. At 55px and 61px, Japanese and Arabic still have too little usable width after padding."
    }
